{"title": "Cortex XDR explorer - endpoint estate", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "description": "Endpoints by operating system and protection state",
  "autosize": {
    "type": "fit",
    "contains": "padding"
  },
  "padding": 4,
  "data": [
    {
      "name": "raw",
      "url": {
        "%context%": true,
        "index": "wazuh-alerts-*",
        "body": {
          "size": 0,
          "aggs": {
            "scoped": {
              "filter": {
                "bool": {
                  "filter": [
                    {
                      "term": {
                        "data.integration": "cortex_xdr"
                      }
                    },
                    {
                      "term": {
                        "data.cortex.event_type": "endpoint"
                      }
                    }
                  ]
                }
              },
              "aggs": {
                "b": {
                  "terms": {
                    "field": "data.cortex.endpoint_id",
                    "size": 10000
                  },
                  "aggs": {
                    "latest": {
                      "top_hits": {
                        "size": 1,
                        "sort": [
                          {
                            "timestamp": {
                              "order": "desc"
                            }
                          }
                        ],
                        "_source": {
                          "includes": [
                            "data.cortex.endpoint_id",
                            "data.cortex.endpoint_name",
                            "data.cortex.os_type",
                            "data.cortex.endpoint_type",
                            "data.cortex.operational_status",
                            "data.cortex.endpoint_status",
                            "data.cortex.content_status",
                            "data.cortex.is_isolated",
                            "data.cortex.endpoint_version",
                            "data.cortex.assigned_prevention_policy",
                            "data.cortex.domain"
                          ]
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      },
      "format": {
        "property": "aggregations.scoped.b.buckets"
      },
      "transform": [
        {
          "type": "formula",
          "expr": "datum.latest.hits.hits[0]._source.data.cortex",
          "as": "c"
        },
        {
          "type": "formula",
          "expr": "replace(datum.c.os_type + '', 'AGENT_OS_', '')",
          "as": "os"
        },
        {
          "type": "formula",
          "expr": "replace(datum.c.endpoint_type + '', 'AGENT_TYPE_', '')",
          "as": "etype"
        },
        {
          "type": "formula",
          "expr": "indexof([\"PROTECTED\", \"PARTIALLY_PROTECTED\", \"UNPROTECTED\"], datum.c.operational_status) >= 0 ? datum.c.operational_status : 'other'",
          "as": "prot"
        },
        {
          "type": "formula",
          "expr": "1",
          "as": "count"
        },
        {
          "type": "aggregate",
          "groupby": [
            "os",
            "prot"
          ],
          "fields": [
            "count"
          ],
          "ops": [
            "sum"
          ],
          "as": [
            "count"
          ]
        },
        {
          "type": "filter",
          "expr": "datum.count > 0"
        },
        {
          "type": "formula",
          "expr": "({\"PROTECTED\": \"#54B399\", \"PARTIALLY_PROTECTED\": \"#D6BF57\", \"UNPROTECTED\": \"#E7664C\", \"other\": \"#98A2B3\"})[datum.prot] || '#98A2B3'",
          "as": "prot_hex"
        },
        {
          "type": "formula",
          "expr": "indexof([\"PROTECTED\", \"PARTIALLY_PROTECTED\", \"UNPROTECTED\", \"other\"], datum.prot)",
          "as": "prot_ord"
        },
        {
          "type": "formula",
          "expr": "(datum.prot_ord < 10 ? '0' : '') + datum.prot_ord + ' ' + datum.prot",
          "as": "prot_key"
        }
      ]
    },
    {
      "name": "tree",
      "source": "raw",
      "transform": [
        {
          "type": "nest",
          "keys": [
            "os"
          ],
          "generate": true
        },
        {
          "type": "treemap",
          "field": "count",
          "method": "squarify",
          "padding": 3,
          "paddingTop": 20,
          "round": true,
          "sort": {
            "field": "count",
            "order": "descending"
          },
          "size": [
            {
              "signal": "width"
            },
            {
              "signal": "height"
            }
          ]
        }
      ]
    },
    {
      "name": "leaves",
      "source": "tree",
      "transform": [
        {
          "type": "filter",
          "expr": "!datum.children"
        }
      ]
    },
    {
      "name": "groups",
      "source": "tree",
      "transform": [
        {
          "type": "filter",
          "expr": "datum.children && datum.depth > 0"
        }
      ]
    }
  ],
  "scales": [
    {
      "name": "c",
      "type": "ordinal",
      "domain": {
        "data": "raw",
        "field": "prot",
        "sort": {
          "op": "min",
          "field": "prot_ord"
        }
      },
      "range": {
        "data": "raw",
        "field": "prot_hex",
        "sort": {
          "op": "min",
          "field": "prot_ord"
        }
      }
    }
  ],
  "legends": [
    {
      "fill": "c",
      "orient": "bottom",
      "direction": "horizontal",
      "title": null,
      "symbolType": "square",
      "columnPadding": 14
    }
  ],
  "marks": [
    {
      "type": "rect",
      "from": {
        "data": "groups"
      },
      "encode": {
        "update": {
          "x": {
            "field": "x0"
          },
          "y": {
            "field": "y0"
          },
          "x2": {
            "field": "x1"
          },
          "y2": {
            "field": "y1"
          },
          "fill": {
            "value": "#F5F7FA"
          },
          "stroke": {
            "value": "#D3DAE6"
          },
          "cornerRadius": {
            "value": 4
          }
        }
      }
    },
    {
      "type": "text",
      "from": {
        "data": "groups"
      },
      "interactive": false,
      "encode": {
        "update": {
          "x": {
            "signal": "datum.x0 + 6"
          },
          "y": {
            "signal": "datum.y0 + 13"
          },
          "fontSize": {
            "value": 12
          },
          "fontWeight": {
            "value": "bold"
          },
          "fill": {
            "value": "#343741"
          },
          "text": {
            "field": "key"
          },
          "opacity": {
            "signal": "(datum.x1 - datum.x0) > 60 ? 1 : 0"
          }
        }
      }
    },
    {
      "type": "rect",
      "from": {
        "data": "leaves"
      },
      "encode": {
        "enter": {
          "tooltip": {
            "signal": "datum.os + ' / ' + datum.prot + ': ' + datum.count"
          }
        },
        "update": {
          "x": {
            "field": "x0"
          },
          "y": {
            "field": "y0"
          },
          "x2": {
            "field": "x1"
          },
          "y2": {
            "field": "y1"
          },
          "fill": {
            "scale": "c",
            "field": "prot"
          },
          "stroke": {
            "value": "#fff"
          },
          "strokeWidth": {
            "value": 1
          },
          "cornerRadius": {
            "value": 2
          }
        },
        "hover": {
          "fillOpacity": {
            "value": 0.8
          }
        }
      }
    },
    {
      "type": "text",
      "from": {
        "data": "leaves"
      },
      "interactive": false,
      "encode": {
        "update": {
          "x": {
            "signal": "(datum.x0 + datum.x1) / 2"
          },
          "y": {
            "signal": "(datum.y0 + datum.y1) / 2"
          },
          "align": {
            "value": "center"
          },
          "baseline": {
            "value": "middle"
          },
          "fontSize": {
            "signal": "min(22, max(10, (datum.y1 - datum.y0) / 4))"
          },
          "fontWeight": {
            "value": "bold"
          },
          "fill": {
            "value": "#fff"
          },
          "text": {
            "field": "count"
          },
          "opacity": {
            "signal": "(datum.x1 - datum.x0) > 26 && (datum.y1 - datum.y0) > 16 ? 1 : 0"
          }
        }
      }
    }
  ]
}"}}

