{"title": "Cortex XDR explorer - alerts by detection day", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": {
      "%context%": true,
      "index": "wazuh-alerts-*",
      "body": {
        "size": 0,
        "aggs": {
          "scoped": {
            "filter": {
              "bool": {
                "filter": [
                  {
                    "term": {
                      "data.integration": "cortex_xdr"
                    }
                  },
                  {
                    "term": {
                      "data.cortex.event_type": "alert"
                    }
                  }
                ]
              }
            },
            "aggs": {
              "b": {
                "terms": {
                  "script": {
                    "source": "if (doc[params.f].size() == 0) return 'none';String v = doc[params.f].value;if (v.indexOf('T') > 0) return v.substring(0, params.n);long ms = (long) Double.parseDouble(v);return java.time.Instant.ofEpochMilli(ms).toString().substring(0, params.n);",
                    "lang": "painless",
                    "params": {
                      "f": "data.cortex.detection_timestamp",
                      "n": 10
                    }
                  },
                  "size": 5000
                },
                "aggs": {
                  "inner": {
                    "terms": {
                      "field": "data.cortex.severity",
                      "size": 6
                    },
                    "aggs": {
                      "n": {
                        "cardinality": {
                          "field": "data.cortex.alert_id"
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      },
      "%timefield%": "timestamp"
    },
    "format": {
      "property": "aggregations.scoped.b.buckets"
    }
  },
  "transform": [
    {
      "filter": "datum.key !== 'none'"
    },
    {
      "flatten": [
        "inner.buckets"
      ],
      "as": [
        "inner"
      ]
    },
    {
      "calculate": "datum.inner.n.value",
      "as": "n"
    },
    {
      "filter": "datum.n > 0"
    },
    {
      "calculate": "toDate(datum.key + 'T00:00:00Z')",
      "as": "t"
    },
    {
      "calculate": "indexof([\"critical\", \"high\", \"medium\", \"low\", \"informational\"], datum.inner.key) >= 0 ? datum.inner.key : 'other'",
      "as": "color"
    },
    {
      "calculate": "({\"critical\": \"#BD271E\", \"high\": \"#E7664C\", \"medium\": \"#D6BF57\", \"low\": \"#54B399\", \"informational\": \"#98A2B3\", \"other\": \"#D3DAE6\"})[datum.color] || '#D3DAE6'",
      "as": "color_hex"
    },
    {
      "calculate": "indexof([\"critical\", \"high\", \"medium\", \"low\", \"informational\", \"other\"], datum.color)",
      "as": "color_ord"
    },
    {
      "calculate": "(datum.color_ord < 10 ? '0' : '') + datum.color_ord + ' ' + datum.color",
      "as": "color_key"
    }
  ],
  "mark": {
    "type": "bar",
    "cornerRadiusTopLeft": 1,
    "cornerRadiusTopRight": 1
  },
  "encoding": {
    "x": {
      "field": "t",
      "type": "temporal",
      "timeUnit": "utcyearmonthdate",
      "title": null,
      "axis": {
        "labelFontSize": 10,
        "grid": false
      }
    },
    "y": {
      "field": "n",
      "type": "quantitative",
      "aggregate": "sum",
      "title": "Alerts",
      "stack": "zero",
      "axis": {
        "tickMinStep": 1,
        "format": ",d",
        "gridColor": "#EEF0F3"
      }
    },
    "color": {
      "field": "color_key",
      "type": "nominal",
      "title": "Severity",
      "legend": {
        "orient": "right",
        "labelLimit": 180,
        "symbolType": "circle",
        "labelExpr": "slice(datum.label, 3)"
      },
      "scale": {
        "range": {
          "field": "color_hex"
        }
      }
    },
    "tooltip": [
      {
        "field": "t",
        "type": "temporal",
        "timeUnit": "utcyearmonthdate",
        "title": "When"
      },
      {
        "field": "color",
        "title": "Split"
      },
      {
        "field": "n",
        "aggregate": "sum",
        "title": "Count"
      }
    ]
  },
  "config": {
    "view": {
      "stroke": null
    }
  }
}"}}

